/** Metadata stored on-chain for each agent wallet */
export interface RawAgentInfo {
  /** Whether this agent is currently active */
  active: boolean;
  /** The agent's Stellar address (its wallet) */
  address: string;
  /** Ledger number when the agent was created */
  created_at: number;
  /** Human-readable name for the agent */
  name: string;
  /** Owner who controls this agent */
  owner: string;
  /** Total operations this agent has performed */
  total_ops: bigint;
}

export function decodeAgentInfo(value: unknown): RawAgentInfo {
  const v = expectRecord(value, 'AgentInfo');
  return {
    active: expectBool(v.active, 'AgentInfo.active'),
    address: expectString(v.address, 'AgentInfo.address'),
    created_at: expectU32(v.created_at, 'AgentInfo.created_at'),
    name: expectString(v.name, 'AgentInfo.name'),
    owner: expectString(v.owner, 'AgentInfo.owner'),
    total_ops: expectBigInt(v.total_ops, 'AgentInfo.total_ops'),
  };
}

// ─── SpendPeriod ───────────────────────────────────────────────────────────────

/** Period over which a spend limit resets */
export const RAW_SPEND_PERIOD_VARIANTS = ['per_ledger', 'hourly', 'daily'] as const;
export type RawSpendPeriod = (typeof RAW_SPEND_PERIOD_VARIANTS)[number];

// ─── Channel ───────────────────────────────────────────────────────────────────

/** A configured payment channel authorizing an agent to spend */
export interface RawChannel {
  /** Whether this channel is open */
  active: boolean;
  /** Agent address authorized to spend */
  agent: string;
  /**
   * Sum of the per-recipient voucher allocations currently reserved.
   * `collateral - allocated` is what the on-chain `pay` path may spend.
   * Keeping the two apart is what makes "a voucher payout never exceeds the
   * deposit" provable rather than incidental.
   */
  allocated: bigint;
  /**
   * Tokens this contract actually holds for this channel.
   * Added by the voucher work, and a bug fix in its own right: before it,
   * `open_channel`'s `deposit` was validated, transferred and then never
   * stored, so every channel drew on one commingled pool and `total_spent`
   * was bounded by nothing — `spent_this_period` resets each period, so an
   * agent could spend `limit_per_period` per period indefinitely out of
   * other owners' deposits. Nothing can pay out more than this.
   */
  collateral: bigint;
  /** Ledgers a unilateral close stays open for challenge. */
  dispute_ledgers: number;
  /** Max spend per period (in stroops / token base units) */
  limit_per_period: bigint;
  /** Owner who funded this channel */
  owner: string;
  /** Period type */
  period: RawSpendPeriod;
  /** Ledger number when current period started */
  period_start_ledger: number;
  /** Amount spent in the current period */
  spent_this_period: bigint;
  /** Token contract address (e.g. USDC) */
  token: string;
  /** Total lifetime spend through this channel */
  total_spent: bigint;
  /**
   * Ed25519 public key authorised to sign vouchers for this channel.
   * `None` until `enable_vouchers`. Explicit rather than derived from
   * `agent`: a contract cannot recover a key from an `Address`, and keeping
   * the voucher key separate from the on-chain identity means it can live in
   * a signing service and rotate independently.
   */
  voucher_signer: Uint8Array | null;
}

export function decodeChannel(value: unknown): RawChannel {
  const v = expectRecord(value, 'Channel');
  return {
    active: expectBool(v.active, 'Channel.active'),
    agent: expectString(v.agent, 'Channel.agent'),
    allocated: expectBigInt(v.allocated, 'Channel.allocated'),
    collateral: expectBigInt(v.collateral, 'Channel.collateral'),
    dispute_ledgers: expectU32(v.dispute_ledgers, 'Channel.dispute_ledgers'),
    limit_per_period: expectBigInt(v.limit_per_period, 'Channel.limit_per_period'),
    owner: expectString(v.owner, 'Channel.owner'),
    period: expectEnumTag(v.period, RAW_SPEND_PERIOD_VARIANTS, 'Channel.period') as RawSpendPeriod,
    period_start_ledger: expectU32(v.period_start_ledger, 'Channel.period_start_ledger'),
    spent_this_period: expectBigInt(v.spent_this_period, 'Channel.spent_this_period'),
    token: expectString(v.token, 'Channel.token'),
    total_spent: expectBigInt(v.total_spent, 'Channel.total_spent'),
    voucher_signer: expectOptional(v.voucher_signer, (value) => expectBytes(value, 'Channel.voucher_signer')),
  };
}

